#include <iostream>
#include <vector>
using namespace std;

int partition(vector<int>& A, int p, int r){

	int x = A[r];
	int i = p - 1;
	
	for(int j = p; j <= r-1;j++){

		if(A[j] <= x){
			i = i + 1;
			swap(A[i],A[j]);
		}
	}

	swap(A[i+1],A[r]);
	
	return i+1;
}


void quickSort(vector<int>& A, int p, int r){

	if(p < r){

		int q = partition(A,p,r);
		quickSort(A,p,q-1);
		quickSort(A,q+1,r);
	}

}


void printArray(vector<int>& A){

	for(int i=0; i < A.size(); i++){

		cout << A[i] << ", ";
	}
	cout << endl;
}

bool listSorted(vector<int>& A){

	for(int i=1; i < A.size();i++){

		if(A[i-1] > A[i]) return false;

	}

	return true;


}









